contract.content:
{
  "action": "execute",
  "archetype": "ai-tool",
  "message": "Building an AI knowledge assistant where employees ask plain-English questions and get cited answers drawn from indexed internal documents. Admins connect SharePoint sources, trigger ingestion, review an audit log of Q&A, and see a dashboard of top questions, knowledge gaps, and most-cited docs. Employees can upload ad-hoc PDFs to fill gaps. A weekly email digest summarizes top questions and knowledge gaps for leadership. Documents carry region/team metadata so answers reflect cross-region institutional knowledge and lessons learned.",
  "flags": [
    "has-users",
    "has-admin",
    "ai-rag",
    "sharepoint",
    "file-uploads",
    "notifications-email"
  ],
  "tasks": [
    {
      "scope": "database",
      "summary": "Set up the storage for users, knowledge sources, documents, questions, answers, citations, and an audit log of activity.",
      "task": "Tables: users, sources, documents, questions, answers, citations, audit_log, digest_runs. Indexes: FK columns, documents(source_id), questions(created_at DESC), citations(answer_id), audit_log(created_at DESC). Column-level contract: data_model.",
      "dockerfile": "Dockerfile.postgres",
      "rules": [],
      "snippets": [],
      "primarySnippet": null
    },
    {
      "scope": "vectordb",
      "summary": "Set up the semantic search index so the assistant can retrieve relevant document chunks for any question.",
      "task": "pgvector extension. Table: doc_chunks(id SERIAL PK, document_id INTEGER NOT NULL, chunk_index INTEGER NOT NULL, content TEXT NOT NULL, region TEXT, team TEXT, embedding vector(3072) NOT NULL, created_at TIMESTAMPTZ DEFAULT now()). Index: HNSW on embedding (cosine). Embedding model: text-embedding-3-large via MGA.",
      "dockerfile": "Dockerfile.pgvector",
      "rules": [],
      "snippets": [],
      "primarySnippet": "vectordb/vectordb-connections.ts"
    },
    {
      "scope": "backend",
      "summary": "Build the API that answers questions with citations, ingests SharePoint and uploaded docs, exposes admin dashboard data, and sends a weekly leadership digest email.",
      "task": "Data: pg Pool from env (postgres + pgvector). Endpoints + bodies: api_contract. Behaviors + rules + side-effects: business_logic_contract. Auth: x-amzn-oidc-data JWT sub/email; first-login upserts users row. RAG: on POST /questions, embed query via MGA text-embedding-3-large, top-k cosine search doc_chunks, call MGA chat assistant 'default' with retrieved context, persist answer + citations, log to audit_log; flag low-confidence answers as knowledge gaps. Uploads: multer memory storage, parse+chunk+embed inline (disk ephemeral). SharePoint: admin registers source, ingestion job fetches+chunks+embeds. Weekly digest: cron job aggregates top questions + low-confidence gaps, sends email to admins. List endpoints paginated (?limit=50&offset=0), newest-first. Validate all POST bodies; uniform {error} on 4xx/5xx.",
      "dockerfile": "Dockerfile.node",
      "rules": [],
      "snippets": [],
      "primarySnippet": "backend/express-server-template.ts"
    },
    {
      "scope": "frontend",
      "summary": "Build the UI where employees ask questions and read cited answers, upload documents, and where admins manage sources and view the knowledge dashboard.",
      "task": "Views + components: ui_contract. Endpoints + body shapes: api_contract (prepend /api/). Employee flow: AskBar → AnswerView with inline CitationList linking to SourceViewer. UploadPanel for ad-hoc PDFs. Admin flow: SourcesManager (connect SharePoint, trigger ingest), AuditLogTable, KnowledgeDashboard (top questions, knowledge gaps, most-cited docs). UI copy uses 'institutional knowledge' and 'lessons learned' framing where natural. States: spinner during retrieval, empty CTA, toast on 4xx/5xx, 404 page, disabled submit during POST. Responsive.",
      "dockerfile": "Dockerfile.react",
      "rules": [],
      "snippets": [],
      "primarySnippet": "frontend/AppScaffold.tsx"
    },
    {
      "scope": "integration",
      "summary": "Wire all services together so the app runs end-to-end locally.",
      "task": "Wire database, vectordb, backend, frontend. Backend env: DATABASE_HOST=database, DATABASE_PORT=5432, DATABASE_NAME=knowledge, DATABASE_USER=knowledge_user, DATABASE_PASSWORD=localdev123, VECTORDB_HOST=vectordb, VECTORDB_PORT=5433, VECTORDB_NAME=knowledge_vec, VECTORDB_USER=knowledge_vec_user, VECTORDB_PASSWORD=localdev123, MGA_API_KEY, MGA_ASSISTANT_KEY=default. nginx.local.conf proxy /api→backend:3000. depends_on chain: database+vectordb → backend → frontend. Healthchecks per service. Named volumes for postgres + pgvector.",
      "dockerfile": null,
      "rules": [],
      "snippets": [],
      "primarySnippet": "integration/docker-compose-fullstack.yml"
    }
  ],
  "data_model": {
    "tables": [
      {
        "name": "users",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "oidc_sub", "type": "TEXT UNIQUE NOT NULL"},
          {"name": "email", "type": "VARCHAR(255) NOT NULL"},
          {"name": "role", "type": "VARCHAR(32) NOT NULL DEFAULT 'employee'"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT now()"}
        ]
      },
      {
        "name": "sources",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "kind", "type": "VARCHAR(32) NOT NULL"},
          {"name": "name", "type": "VARCHAR(255) NOT NULL"},
          {"name": "config", "type": "JSONB NOT NULL DEFAULT '{}'::jsonb"},
          {"name": "last_indexed_at", "type": "TIMESTAMPTZ"},
          {"name": "created_by", "type": "INTEGER REFERENCES users(id)"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT now()"}
        ]
      },
      {
        "name": "documents",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "source_id", "type": "INTEGER REFERENCES sources(id)"},
          {"name": "title", "type": "VARCHAR(512) NOT NULL"},
          {"name": "uri", "type": "TEXT"},
          {"name": "region", "type": "VARCHAR(64)"},
          {"name": "team", "type": "VARCHAR(64)"},
          {"name": "uploaded_by", "type": "INTEGER REFERENCES users(id)"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT now()"}
        ]
      },
      {
        "name": "questions",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "user_id", "type": "INTEGER NOT NULL REFERENCES users(id)"},
          {"name": "text", "type": "TEXT NOT NULL"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT now()"}
        ]
      },
      {
        "name": "answers",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "question_id", "type": "INTEGER NOT NULL REFERENCES questions(id)"},
          {"name": "text", "type": "TEXT NOT NULL"},
          {"name": "confidence", "type": "REAL"},
          {"name": "is_knowledge_gap", "type": "BOOLEAN NOT NULL DEFAULT false"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT now()"}
        ]
      },
      {
        "name": "citations",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "answer_id", "type": "INTEGER NOT NULL REFERENCES answers(id)"},
          {"name": "document_id", "type": "INTEGER NOT NULL REFERENCES documents(id)"},
          {"name": "excerpt", "type": "TEXT"},
          {"name": "score", "type": "REAL"}
        ]
      },
      {
        "name": "audit_log",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "user_id", "type": "INTEGER REFERENCES users(id)"},
          {"name": "action", "type": "VARCHAR(64) NOT NULL"},
          {"name": "entity_type", "type": "VARCHAR(64)"},
          {"name": "entity_id", "type": "INTEGER"},
          {"name": "metadata", "type": "JSONB NOT NULL DEFAULT '{}'::jsonb"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT now()"}
        ]
      },
      {
        "name": "digest_runs",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "period_start", "type": "TIMESTAMPTZ NOT NULL"},
          {"name": "period_end", "type": "TIMESTAMPTZ NOT NULL"},
          {"name": "summary", "type": "JSONB NOT NULL"},
          {"name": "sent_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT now()"}
        ]
      }
    ]
  },
  "api_contract": {
    "version": 1,
    "endpoints": [
      {
        "method": "GET",
        "path": "/whoami",
        "response": {"status": 200, "body": "{ id, email, role }"}
      },
      {
        "method": "POST",
        "path": "/questions",
        "request": {"text": "string required"},
        "response": {"status": 201, "body": "{ question_id, answer: { id, text, confidence, is_knowledge_gap }, citations: [{ document_id, title, uri, excerpt, score }] }"}
      },
      {
        "method": "GET",
        "path": "/questions",
        "response": {"status": 200, "body": "{ items: [{ id, text, created_at, answer_preview }], total }"}
      },
      {
        "method": "GET",
        "path": "/questions/:id",
        "response": {"status": 200, "body": "{ id, text, answer, citations }"}
      },
      {
        "method": "GET",
        "path": "/documents/:id",
        "response": {"status": 200, "body": "{ id, title, uri, region, team, source }"}
      },
      {
        "method": "POST",
        "path": "/documents/upload",
        "request": {"file": "multipart required", "region": "string optional", "team": "string optional"},
        "response": {"status": 201, "body": "{ id, title, chunk_count }"}
      },
      {
        "method": "GET",
        "path": "/admin/sources",
        "response": {"status": 200, "body": "{ items: [{ id, kind, name, last_indexed_at }] }"}
      },
      {
        "method": "POST",
        "path": "/admin/sources",
        "request": {"kind": "string required (sharepoint|teams|wiki)", "name": "string required", "config": "object required"},
        "response": {"status": 201, "body": "{ id, kind, name }"}
      },
      {
        "method": "POST",
        "path": "/admin/sources/:id/ingest",
        "response": {"status": 202, "body": "{ source_id, job_status }"}
      },
      {
        "method": "GET",
        "path": "/admin/audit",
        "response": {"status": 200, "body": "{ items: [{ id, user_email, action, entity_type, entity_id, metadata, created_at }], total }"}
      },
      {
        "method": "GET",
        "path": "/admin/dashboard",
        "response": {"status": 200, "body": "{ top_questions: [...], knowledge_gaps: [...], most_cited_documents: [...] }"}
      },
      {
        "method": "POST",
        "path": "/admin/digest/run",
        "response": {"status": 200, "body": "{ digest_run_id, sent_to: [emails] }"}
      },
      {
        "method": "GET",
        "path": "/admin/digest",
        "response": {"status": 200, "body": "{ items: [{ id, period_start, period_end, summary, sent_at }] }"}
      }
    ]
  },
  "ui_contract": {
    "primary_view": "ask box where employees type a question and read the cited answer",
    "primary_action": "ask a question of the institutional knowledge base",
    "secondary_views": [
      "answer detail with citations and source excerpts",
      "document/source viewer",
      "ad-hoc document upload panel",
      "admin sources manager",
      "admin audit log",
      "admin knowledge dashboard"
    ],
    "components": [
      {"name": "AskBar", "role": "primary natural-language question input"},
      {"name": "AnswerView", "role": "renders the AI-generated answer with confidence indicator"},
      {"name": "CitationList", "role": "lists cited source documents under an answer"},
      {"name": "SourceViewer", "role": "shows the underlying document or excerpt for a citation"},
      {"name": "QuestionHistory", "role": "employee's recent questions and answers"},
      {"name": "UploadPanel", "role": "employee uploads ad-hoc PDF/doc to expand the knowledge base"},
      {"name": "SourcesManager", "role": "admin connects SharePoint/Teams/wiki sources and triggers ingestion"},
      {"name": "AuditLogTable", "role": "admin reviews questions asked, answers given, citations used"},
      {"name": "KnowledgeDashboard", "role": "admin sees top questions, knowledge gaps, most-cited documents"},
      {"name": "DigestPanel", "role": "admin views past weekly leadership digests and triggers a run"}
    ]
  },
  "business_logic_contract": {
    "triggers": [
      {"event": "user_first_login", "action": "create users row from OIDC claims (sub, email); default role=employee"},
      {"event": "question_asked", "action": "embed query, retrieve top-k chunks from pgvector, call MGA chat assistant, persist question+answer+citations, log to audit_log"},
      {"event": "answer_low_confidence", "action": "mark answer is_knowledge_gap=true for dashboard surfacing"},
      {"event": "document_uploaded", "action": "parse from memory buffer, chunk text, embed via MGA text-embedding-3-large, insert into doc_chunks with region/team metadata"},
      {"event": "source_ingest_triggered", "action": "fetch documents from SharePoint/Teams/wiki source, chunk, embed, insert into doc_chunks; update sources.last_indexed_at"},
      {"event": "weekly_cron", "action": "aggregate top questions and knowledge gaps for the past 7 days, write digest_runs row, email summary to all admin users"}
    ],
    "rules": [
      "employees can ask questions, upload documents, and view their own question history",
      "employees can view any cited document (knowledge base is org-wide)",
      "/admin/* endpoints require role='admin' — 403 otherwise",
      "only admins can connect sources, trigger ingestion, view audit log, view dashboard, view/run digests",
      "every uploaded document must be embedded into pgvector at upload time (disk is ephemeral)",
      "every question/answer/citation event is recorded in audit_log",
      "all list endpoints paginated (?limit=50&offset=0), newest-first"
    ],
    "side_effects": [
      "audit log on every question asked, document uploaded, source created, source ingested, and digest run"
    ]
  },
  "vector_engine": "pgvector",
  "mga_assistants": [
    {
      "key": "default",
      "name": "Institutional Knowledge Assistant",
      "description": "Answers employee questions about internal company knowledge using indexed SharePoint, wiki, and project documents, returning cited sources and surfacing lessons learned from prior initiatives.",
      "model": "claude-opus-4.7",
      "tool_keys": [],
      "starter_messages": [
        "What lessons did we learn from past launches in this region?",
        "Have we built something similar for a client before?",
        "Which policies cover remote work across regions?"
      ]
    }
  ]
}
